# Generated by build.py from recipe.yml for recipe smtp-survive-a-temporary-rcpt-failure. Do not edit.
Set-Location $PSScriptRoot
[IO.File]::WriteAllText((Join-Path $PWD 'order.eml'), "From: app@example.com`nTo: ann@example.com`nSubject: Order 1042 has shipped`n`nYour order is on its way.`n")
[IO.File]::WriteAllText((Join-Path $PWD 'send-retrying.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Sends one message with curl, retrying only a temporary (4xx) refusal, at most <tries> tries in all.`n# Usage: sh send-retrying.sh <tries> <curl arguments...>`ntries=`$1`nshift`nwhile :; do`n  code=`$(curl -s -w `"%{response_code}`" `"`$@`")`n  status=`$?`n  if [ `"`$status`" -eq 0 ]; then`n    echo `"sent: `$code`"`n    exit 0`n  fi`n  tries=`$((tries - 1))`n  case `$code in`n    4??)`n      if [ `"`$tries`" -gt 0 ]; then`n        echo `"temporary: `$code, retrying`"`n        sleep 1`n        continue`n      fi ;;`n  esac`n  echo `"gave up: `$code`"`n  exit `"`$status`"`ndone`n")
$server0 = Start-Process surl -ArgumentList '-v', '--log-file', 'surl.log', '--mail-domain', 'example.com', '--mailbox', 'app@example.com:apppass', '--mailbox', 'ann@example.com:annpass', '--fault', '"error;scheme=smtp;command=RCPT;reply=451', '4.3.0', 'try', 'later;times=1"', 'smtp://127.0.0.1:8080/', 'imap://127.0.0.1:8081/' -PassThru -NoNewWindow
Start-Sleep 1
try { sh send-retrying.sh 3 --crlf -u app@example.com:apppass --mail-from app@example.com --mail-rcpt ann@example.com -T order.eml smtp://127.0.0.1:8080/example.com && curl -s -u ann@example.com:annpass -X "STATUS INBOX (MESSAGES)" imap://127.0.0.1:8081/ } finally { Stop-Process $server0 }
